tool_args.command:
source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 -c "
from modelscope.hub.api import HubApi
api = HubApi()
# Try listing models from known owners
for owner in ['LLM-Research', 'AI-ModelScope', 'qwen']:
    try:
        result = api.list_models(owner)
        models = result.get('Models', [])
        for m in models:
            name = m.get('Name', m.get('ModelId', ''))
            if 'AWQ' in name.upper() and '70B' in name:
                print(f'{owner}: {name}')
    except Exception as e:
        print(f'{owner}: ERROR {e}')
"
